void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec4 buffer0 = texelFetch(iChannel0, ivec2(fragCoord), 0);
    vec4 buffer1 = texelFetch(iChannel1, ivec2(fragCoord), 0);

    float sillyMousex = iMouse.x;

    if(iMouse.x == 0.0)
    {
        sillyMousex = iResolution.x/2.0;
    }

    vec4 selBuffer = buffer1;

    if(fragCoord.x > sillyMousex)
    {
        selBuffer = buffer0;
    }

    selBuffer = vec4(selBuffer.xy,sqrt(selBuffer.z),selBuffer.w);

    #ifdef SHOW_UV
    fragColor = selBuffer;
    return;
    #endif
    fragColor = vec4(selBuffer.z);
}

#define SHOW_UV

uint hash(inout uint x ) {
    x += ( x << 10u );
    x ^= ( x >>  6u );
    x += ( x <<  3u );
    x ^= ( x >> 11u );
    x += ( x << 15u );
    return x;
}


float rand(inout uint seed)
{
    return fract(float(hash(seed))/ 4294967296.0);//4294967296 2 ^ 32 / 32 bit unsigned integer limit
}

#define KERNAL_SIZE 5
#define DENSITY 0.03

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = vec4(0.0);

    float modFrame = 2.0 + mod(float(iFrame) + iDate.w, 500.0);

    uint seed = uint((fragCoord.y * iResolution.x + fragCoord.x) * modFrame);

    if(iFrame == 2)
    {
        fragColor = vec4(0.0);

        if(rand(seed) > (100.0 - DENSITY) / 100.0)
        {
            fragColor = vec4(fragCoord.xy/iResolution.xy,1.0,0.0);
        }
        return;
    }

    vec4 buffer0 = texelFetch(iChannel0, ivec2(fragCoord), 0);

    if(buffer0 != vec4(0.0))
    {
        fragColor = buffer0;
        return;
    }

    float maxBright = 0.0;

    for(int y=-KERNAL_SIZE; y<=KERNAL_SIZE; y++)
    {
        for(int x=-KERNAL_SIZE; x<=KERNAL_SIZE; x++)
        {   
            float dist = distance(vec2(0.0), vec2(x,y));

            if(dist > float(KERNAL_SIZE))
            {
                continue;
            }

            vec4 sample0 = texelFetch(iChannel0, ivec2(fragCoord) + ivec2(x,y), 0);

            if(sample0.z > maxBright)
            {
                maxBright = sample0.z;
                fragColor = vec4(sample0.xy,1.0 / ((1.0 / sample0.z) + dist),0.0);
            }
        }
    }
}

#define POINT_NUM 100

#define SHOW_POINTS false

struct Point{
    vec4 color;
    vec2 pos;
};

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec4 buffer0 = texelFetch(iChannel0, ivec2(fragCoord), 0);

    if(iFrame > 2)
    {
        fragColor = buffer0;
        return;
    }

    Point pointList[POINT_NUM];

    float modFrame = 2.0 + mod(float(iFrame) + iDate.w, 500.0);

    uint seed = uint((fragCoord.y * iResolution.x + fragCoord.x) * modFrame);

    uint frameSeed = uint(modFrame);

    for(int i=0; i<POINT_NUM; i++)
    {
        vec4 randColor = vec4(rand(frameSeed),rand(frameSeed),rand(frameSeed),rand(frameSeed));
        pointList[i] = Point(randColor, vec2(rand(frameSeed),rand(frameSeed)) * iResolution.xy);
    }

    float minDist = 100000000000.0;
    vec4 color = vec4(0.0);

    for(int i=0; i<POINT_NUM; i++)
    {
        float dist = distance(fragCoord.xy, pointList[i].pos);

        if(dist < minDist)
        {
            minDist = dist;
            fragColor = vec4(pointList[i].pos/iResolution.xy,1.0 / (dist+1.0),0.0);
        }
    }
}
